// T-158 (E3 lane D): the ONE typed API client every screen uses.
// The `paths` types come from the GENERATED ui/src/api/openapi.d.ts - generated by the build
// from the backend's own OpenAPI document (npm run generate:client), never hand-edited, so the
// console's calls are checked against the backend's real contract (E3-F3-S1: no mock can hide
// a mismatch). The base URL comes from VITE_API_URL (R07: a name only - this file never holds
// a secret value).

import createClient from 'openapi-fetch';
import type { paths } from './openapi.d';

export function createConsoleClient(baseUrl: string) {
  return createClient<paths>({ baseUrl });
}

/** The console's client; the base URL arrives as a runtime variable name, no value in source. */
export const api = createConsoleClient((import.meta.env.VITE_API_URL as string | undefined) ?? '');

export type ConsoleClient = typeof api;